    }

    /** 字幕文本审核状态。 */
    public enum SubtitleTextStatus {
        PENDING, APPROVED
    }

    /** 审核字幕文本版本请求（幂等）；仅 PENDING 可审核。 */
    public record ApproveSubtitleTextRequest(@NotBlank String requestId) {
