    /** 以独立事务写入一条阻断审计；外层发布事务回滚不影响本记录。 */
    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void record(String channelId, LocalDate businessDay, String requestId,
                       String code, String detailJson) {
        // 实现在填充阶段写入。
    }
}

